# frozen_string_literal: true

Valkyrie::MetadataAdapter.register(Valkyrie::Persistence::Postgres::MetadataAdapter.new, :pg_metadata)
Valkyrie.config.metadata_adapter = :pg_metadata

Valkyrie::StorageAdapter.register(
  Valkyrie::Storage::Disk.new(base_path: Rails.root.join('tmp/storage/files')),
  :disk
)
Valkyrie.config.storage_adapter = :disk
Valkyrie.config.indexing_adapter = :null_index

# What an app generated by `rails generate hyrax:install` registers.
Rails.application.reloader.to_prepare do
  [Hyrax::CustomQueries::Navigators::CollectionMembers,
   Hyrax::CustomQueries::Navigators::ChildCollectionsNavigator,
   Hyrax::CustomQueries::Navigators::ParentCollectionsNavigator,
   Hyrax::CustomQueries::Navigators::ChildFileSetsNavigator,
   Hyrax::CustomQueries::Navigators::ChildWorksNavigator,
   Hyrax::CustomQueries::Navigators::ParentWorkNavigator,
   Hyrax::CustomQueries::Navigators::FindFiles,
   Hyrax::CustomQueries::FindAccessControl,
   Hyrax::CustomQueries::FindCollectionsByType,
   Hyrax::CustomQueries::FindFileMetadata,
   Hyrax::CustomQueries::FindIdsByModel,
   Hyrax::CustomQueries::FindManyByAlternateIds,
   Hyrax::CustomQueries::FindModelsByAccess,
   Hyrax::CustomQueries::FindCountBy,
   Hyrax::CustomQueries::FindByDateRange].each do |handler|
    Hyrax.query_service.custom_queries.register_query_handler(handler)
  end
end
